mapper.select:
SELECT id, developer_id, category_id, game_name, description, cover_image, download_link, average_rating, create_time
FROM games
WHERE id = #{id}

mapper.update:
UPDATE games
SET game_name = #{gameName},
    description = #{description},
    cover_image = #{coverImage}
WHERE id = #{id} AND developer_id = #{developerId}
